import{_ as l,a0 as o,w as d,s as c,I as a,x as n,a1 as e,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何構建一台網絡引導服務器（二） | LCTT x X-CMD","titleTemplate":false,"description":"如何構建一台網絡引導服務器（二） | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何構建一台網絡引導服務器（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何構建一台網絡引導服務器（二） | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181212 How to Build a Netboot Server, Part 2","title":"如何構建一台網絡引導服務器（二）","tag":"201812","desc":""},"relativePath":"201812/20181212 How to Build a Netboot Server, Part 2.md","filePath":"[post].md"}'),r={name:"201812/20181212 How to Build a Netboot Server, Part 2.md"};function h(u,s,g,k,f,b){const i=o("Link");return d(),c("div",null,[s[42]||(s[42]=a("h1",{id:"如何構建一台網絡引導服務器-二",tabindex:"-1"},[n("如何構建一台網絡引導服務器（二） "),a("a",{class:"header-anchor",href:"#如何構建一台網絡引導服務器-二","aria-label":"Permalink to “如何構建一台網絡引導服務器（二）”"},"​")],-1)),s[43]||(s[43]=a("p",null,[a("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/12/netboot2-816x345.jpg",alt:""})],-1)),a("p",null,[s[2]||(s[2]=n("在 ",-1)),e(i,{href:"https://linux.cn/article-10379-1.html"},{default:p(()=>[...s[0]||(s[0]=[n("如何構建一台網絡引導服務器（一）",-1)])]),_:1}),s[3]||(s[3]=n(" 的文章中，我們展示瞭如何創建一個網絡引導鏡像，在那個鏡像中使用了一個名為 ",-1)),s[4]||(s[4]=a("code",null,"liveuser",-1)),s[5]||(s[5]=n(" 帳户，它的家目錄位於內存中，重啓後家目錄中的內容將全部消失。然而很多用户都希望機器重啓後保存他們的文件和設置。因此，在本系列的第二部分，我們將向你展示如何在第一部分的基礎上，重新配置網絡引導鏡像，以便 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Active_Directory"},{default:p(()=>[...s[1]||(s[1]=[n("活動目錄",-1)])]),_:1}),s[6]||(s[6]=n(" 中的用户帳户可以進行登錄，然後從一個 NFS 服務器上自動掛載他們的家目錄。",-1))]),s[44]||(s[44]=a("p",null,"本系列的第三部分，我們將向你展示網絡引導客户端如何與中心化配置的 iPXE 引導菜單進行交互。",-1)),s[45]||(s[45]=a("h3",{id:"設置使用-krb5-認證的-nfs4-home-目錄",tabindex:"-1"},[n("設置使用 KRB5 認證的 NFS4 Home 目錄 "),a("a",{class:"header-anchor",href:"#設置使用-krb5-認證的-nfs4-home-目錄","aria-label":"Permalink to “設置使用 KRB5 認證的 NFS4 Home 目錄”"},"​")],-1)),a("p",null,[s[8]||(s[8]=n("按以前的文章 “",-1)),e(i,{href:"https://fedoramagazine.org/secure-nfs-home-directories-kerberos"},{default:p(()=>[...s[7]||(s[7]=[n("使用 Kerberos 強化共享的 NFS Home 目錄安全性",-1)])]),_:1}),s[9]||(s[9]=n("” 的指導來做這個設置。",-1))]),s[46]||(s[46]=t(`<h3 id="刪除-liveuser-帳户" tabindex="-1">刪除 Liveuser 帳户 <a class="header-anchor" href="#刪除-liveuser-帳户" aria-label="Permalink to “刪除 Liveuser 帳户”">​</a></h3><p>刪除本系列文章第一部分中創建的 <code>liveuser</code> 帳户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -i</span></span>
<span class="line"><span># sed -i &#39;/automaticlogin/Id&#39; /fc28/etc/gdm/custom.conf</span></span>
<span class="line"><span># rm -f /fc28/etc/sudoers.d/liveuser</span></span>
<span class="line"><span># for i in passwd shadow group gshadow; do sed -i &#39;/^liveuser:/d&#39; /fc28/etc/$i; done</span></span></code></pre></div><h3 id="配置-ntp、krb5-和-sssd" tabindex="-1">配置 NTP、KRB5 和 SSSD <a class="header-anchor" href="#配置-ntp、krb5-和-sssd" aria-label="Permalink to “配置 NTP、KRB5 和 SSSD”">​</a></h3><p>接下來，我們需要將 NTP、KRB5 和 SSSD 的配置文件複製進客户端使用的鏡像中，以便於它們能夠使用同一個帳户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_HOSTNAME=$(&lt;/etc/hostname)</span></span>
<span class="line"><span># MY_DOMAIN=\${MY_HOSTNAME#*.}</span></span>
<span class="line"><span># dnf -y --installroot=/fc28 install ntp krb5-workstation sssd</span></span>
<span class="line"><span># cp /etc/ntp.conf /fc28/etc</span></span>
<span class="line"><span># chroot /fc28 systemctl enable ntpd.service</span></span>
<span class="line"><span># cp /etc/krb5.conf.d/\${MY_DOMAIN%%.*} /fc28/etc/krb5.conf.d</span></span>
<span class="line"><span># cp /etc/sssd/sssd.conf /fc28/etc/sssd</span></span></code></pre></div><p>在已配置的識別服務的基礎上，重新配置 sssd 提供認證服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -i &#39;/services =/s/$/, pam/&#39; /fc28/etc/sssd/sssd.conf</span></span></code></pre></div><p>另外，配置成確保客户端不能更改這個帳户密碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -i &#39;/id_provider/a \\ \\ ad_maximum_machine_account_password_age = 0&#39; /fc28/etc/sssd/sssd.conf</span></span></code></pre></div><p>另外，複製 nfsnobody 的定義：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># for i in passwd shadow group gshadow; do grep &quot;^nfsnobody:&quot; /etc/$i &gt;&gt; /fc28/etc/$i; done</span></span></code></pre></div><h3 id="加入活動目錄" tabindex="-1">加入活動目錄 <a class="header-anchor" href="#加入活動目錄" aria-label="Permalink to “加入活動目錄”">​</a></h3><p>接下來，你將執行一個 <code>chroot</code> 將客户端鏡像加入到活動目錄。從刪除預置在網絡引導鏡像中同名的計算機帳户開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_USERNAME=jsmith</span></span>
<span class="line"><span># MY_CLIENT_HOSTNAME=$(&lt;/fc28/etc/hostname)</span></span>
<span class="line"><span># adcli delete-computer &quot;\${MY_CLIENT_HOSTNAME%%.*}&quot; -U &quot;$MY_USERNAME&quot;</span></span></code></pre></div><p>在網絡引導鏡像中如果有 <code>krb5.keytab</code> 文件，也刪除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rm -f /fc28/etc/krb5.keytab</span></span></code></pre></div><p><code>chroot</code> 到網絡引導鏡像中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># for i in dev dev/pts dev/shm proc sys run; do mount -o bind /$i /fc28/$i; done</span></span>
<span class="line"><span># chroot /fc28 /usr/bin/bash --login</span></span></code></pre></div><p>執行一個加入操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_USERNAME=jsmith</span></span>
<span class="line"><span># MY_HOSTNAME=$(&lt;/etc/hostname)</span></span>
<span class="line"><span># MY_DOMAIN=\${MY_HOSTNAME#*.}</span></span>
<span class="line"><span># MY_REALM=\${MY_DOMAIN^^}</span></span>
<span class="line"><span># MY_OU=&quot;cn=computers,dc=\${MY_DOMAIN//./,dc=}&quot;</span></span>
<span class="line"><span># adcli join $MY_DOMAIN --login-user=&quot;$MY_USERNAME&quot; --computer-name=&quot;\${MY_HOSTNAME%%.*}&quot; --host-fqdn=&quot;$MY_HOSTNAME&quot; --user-principal=&quot;host/$MY_HOSTNAME@$MY_REALM&quot; --domain-ou=&quot;$MY_OU&quot;</span></span></code></pre></div><p>現在登出 chroot，並清除 root 用户的命令歷史：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># logout</span></span>
<span class="line"><span># for i in run sys proc dev/shm dev/pts dev; do umount /fc28/$i; done</span></span>
<span class="line"><span># &gt; /fc28/root/.bash_history</span></span></code></pre></div><h3 id="安裝和配置-pam-掛載" tabindex="-1">安裝和配置 PAM 掛載 <a class="header-anchor" href="#安裝和配置-pam-掛載" aria-label="Permalink to “安裝和配置 PAM 掛載”">​</a></h3><p>我們希望客户端登入後自動掛載用户家目錄。為實現這個目的，我們將要使用 <code>pam_mount</code> 模組。安裝和配置 <code>pam_mount</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install -y --installroot=/fc28 pam_mount</span></span>
<span class="line"><span># cat &lt;&lt; END &gt; /fc28/etc/security/pam_mount.conf.xml</span></span>
<span class="line"><span>&lt;?xml version=&quot;1.0&quot; encoding=&quot;utf-8&quot; ?&gt;</span></span>
<span class="line"><span>&lt;!DOCTYPE pam_mount SYSTEM &quot;pam_mount.conf.xml.dtd&quot;&gt;</span></span>
<span class="line"><span>&lt;pam_mount&gt;</span></span>
<span class="line"><span>&lt;debug enable=&quot;0&quot; /&gt;</span></span>
<span class="line"><span>&lt;volume uid=&quot;1400000000-1499999999&quot; fstype=&quot;nfs4&quot; server=&quot;$MY_HOSTNAME&quot; path=&quot;/home/%(USER)&quot; mountpoint=&quot;/home/%(USER)&quot; options=&quot;sec=krb5&quot; /&gt;</span></span>
<span class="line"><span>&lt;mkmountpoint enable=&quot;1&quot; remove=&quot;0&quot; /&gt;</span></span>
<span class="line"><span>&lt;msg-authpw&gt;Password:&lt;/msg-authpw&gt;</span></span>
<span class="line"><span>&lt;/pam_mount&gt;</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>重新配置 PAM 去使用 <code>pam_mount</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install -y patch</span></span>
<span class="line"><span># cp -r /fc28/usr/share/authselect/default/sssd /fc28/etc/authselect/custom</span></span>
<span class="line"><span># echo &#39;initgroups: files&#39; &gt;&gt; /fc28/etc/authselect/custom/sssd/nsswitch.conf</span></span>
<span class="line"><span># patch /fc28/etc/authselect/custom/sssd/system-auth &lt;&lt; END</span></span>
<span class="line"><span>@@ -12 +12,2 @@</span></span>
<span class="line"><span>-auth        sufficient                                   pam_sss.so forward_pass</span></span>
<span class="line"><span>+auth        requisite                                    pam_mount.so {include if &quot;with-pammount&quot;}</span></span>
<span class="line"><span>+auth        sufficient                                   pam_sss.so {if &quot;with-pammount&quot;:use_first_pass|forward_pass}</span></span>
<span class="line"><span>@@ -35,2 +36,3 @@</span></span>
<span class="line"><span> session     required                                     pam_unix.so</span></span>
<span class="line"><span>+session     optional                                     pam_mount.so {include if &quot;with-pammount&quot;}</span></span>
<span class="line"><span> session     optional                                     pam_sss.so</span></span>
<span class="line"><span>END</span></span>
<span class="line"><span># patch /fc28/etc/authselect/custom/sssd/password-auth &lt;&lt; END</span></span>
<span class="line"><span>@@ -9 +9,2 @@</span></span>
<span class="line"><span>-auth        sufficient                                   pam_sss.so forward_pass</span></span>
<span class="line"><span>+auth        requisite                                    pam_mount.so {include if &quot;with-pammount&quot;}</span></span>
<span class="line"><span>+auth        sufficient                                   pam_sss.so {if &quot;with-pammount&quot;:use_first_pass|forward_pass}</span></span>
<span class="line"><span>@@ -32,2 +33,3 @@</span></span>
<span class="line"><span> session     required                                     pam_unix.so</span></span>
<span class="line"><span>+session     optional                                     pam_mount.so {include if &quot;with-pammount&quot;}</span></span>
<span class="line"><span> session     optional                                     pam_sss.so</span></span>
<span class="line"><span>END</span></span>
<span class="line"><span># chroot /fc28 authselect select custom/sssd with-pammount --force</span></span></code></pre></div><p>另外，要確保從客户端上總是可解析 NFS 服務器的主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_IP=$(host -t A $MY_HOSTNAME | awk &#39;{print $4}&#39;)</span></span>
<span class="line"><span># echo &quot;$MY_IP $MY_HOSTNAME \${MY_HOSTNAME%%.*}&quot; &gt;&gt; /fc28/etc/hosts</span></span></code></pre></div><p>可選，允許所有用户可以使用 <code>sudo</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo &#39;%users ALL=(ALL) NOPASSWD: ALL&#39; &gt; /fc28/etc/sudoers.d/users</span></span></code></pre></div><h3 id="轉換-nfs-根目錄到一個-iscsi-後備存儲器" tabindex="-1">轉換 NFS 根目錄到一個 iSCSI 後備存儲器 <a class="header-anchor" href="#轉換-nfs-根目錄到一個-iscsi-後備存儲器" aria-label="Permalink to “轉換 NFS 根目錄到一個 iSCSI 後備存儲器”">​</a></h3><p>在一個 nfsroot 連接建立之後，目前版本的 nfs-utils 可能很難為家目錄建立一個從客户端到 NFS 服務器的第二個連接。當嘗試去訪問家目錄時，客户端將被掛起。因此，為了共享網絡引導鏡像，我們將使用一個不同的協議（iSCSI）來規避這個問題。</p><p>首先 <code>chroot</code> 到鏡像中，重新配置它的 <code>initramfs</code>，讓它從一個 iSCSI 根目錄中去引導：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># for i in dev dev/pts dev/shm proc sys run; do mount -o bind /$i /fc28/$i; done</span></span>
<span class="line"><span># chroot /fc28 /usr/bin/bash --login</span></span>
<span class="line"><span># dnf install -y iscsi-initiator-utils</span></span>
<span class="line"><span># sed -i &#39;s/nfs/iscsi/&#39; /etc/dracut.conf.d/netboot.conf</span></span>
<span class="line"><span># echo &#39;omit_drivers+=&quot; qedi &quot;&#39; &gt; /etc/dracut.conf.d/omit-qedi.conf</span></span>
<span class="line"><span># echo &#39;blacklist qedi&#39; &gt; /etc/modprobe.d/blacklist-qedi.conf</span></span>
<span class="line"><span># KERNEL=$(ls -c /lib/modules | head -n 1)</span></span>
<span class="line"><span># INITRD=$(find /boot -name &#39;init*&#39; | grep -m 1 $KERNEL)</span></span>
<span class="line"><span># dracut -f $INITRD $KERNEL</span></span>
<span class="line"><span># logout</span></span>
<span class="line"><span># for i in run sys proc dev/shm dev/pts dev; do umount /fc28/$i; done</span></span>
<span class="line"><span># &gt; /fc28/root/.bash_history</span></span></code></pre></div><p>在測試時，qedi 驅動會破壞 iSCSI，因此我們將它禁用。</p>`,37)),a("p",null,[s[11]||(s[11]=n("接着，創建一個 ",-1)),s[12]||(s[12]=a("code",null,"fc28.img",-1)),s[13]||(s[13]=n()),e(i,{href:"https://en.wikipedia.org/wiki/Sparse_file"},{default:p(()=>[...s[10]||(s[10]=[n("稀疏文件",-1)])]),_:1}),s[14]||(s[14]=n("。這個稀疏文件代表 iSCSI 目標的後備存儲器：",-1))]),s[47]||(s[47]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># FC28_SIZE=$(du -ms /fc28 | cut -f 1)</span></span>
<span class="line"><span># dd if=/dev/zero of=/fc28.img bs=1MiB count=0 seek=$(($FC28_SIZE*2))</span></span></code></pre></div><p>（如果你有一個可使用的獨立分區或磁盤驅動器，也可以用它，而不用再去創建這個稀疏文件了。）</p><p>接着，使用一個文件系統去格式化鏡像、掛載它、然後將網絡引導鏡像複製進去：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkfs -t xfs -L NETROOT /fc28.img</span></span>
<span class="line"><span># TEMP_MNT=$(mktemp -d)</span></span>
<span class="line"><span># mount /fc28.img $TEMP_MNT</span></span>
<span class="line"><span># cp -a /fc28/* $TEMP_MNT</span></span>
<span class="line"><span># umount $TEMP_MNT</span></span></code></pre></div>`,4)),a("p",null,[s[17]||(s[17]=n("在使用 SquashFS 測試時，客户端偶爾會出現小狀況。似乎是因為 SquashFS 在多處理器客户端上沒法執行隨機 I/O。（更多內容見 ",-1)),e(i,{href:"https://chrisdown.name/2018/04/17/kernel-adventures-the-curious-case-of-squashfs-stalls.html"},{default:p(()=>[...s[15]||(s[15]=[n("squashfs 讀取卡頓的奇怪案例",-1)])]),_:1}),s[18]||(s[18]=n("）。如果你希望使用文件系統壓縮來提升吞吐性能，",-1)),e(i,{href:"https://en.wikipedia.org/wiki/ZFS"},{default:p(()=>[...s[16]||(s[16]=[n("ZFS",-1)])]),_:1}),s[19]||(s[19]=n(" 或許是個很好的選擇。",-1))]),a("p",null,[s[23]||(s[23]=n("如果你對 iSCSI 服務器的吞吐性能要求非常高（比如，成百上千的客户端要連接它），可能需要使用帶 ",-1)),e(i,{href:"https://en.wikipedia.org/wiki/Load_balancing_(computing)"},{default:p(()=>[...s[20]||(s[20]=[n("負載均衡",-1)])]),_:1}),s[24]||(s[24]=n(" 的 ",-1)),e(i,{href:"http://docs.ceph.com/docs/mimic/rbd/iscsi-overview/"},{default:p(()=>[...s[21]||(s[21]=[n("Ceph",-1)])]),_:1}),s[25]||(s[25]=n(" 集羣了。更多相關內容，請查看 ",-1)),e(i,{href:"https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/7/html/load_balancer_administration/ceph_example"},{default:p(()=>[...s[22]||(s[22]=[n("使用 HAProxy 和 Keepalived 負載均衡的 Ceph 對象網關",-1)])]),_:1}),s[26]||(s[26]=n("。",-1))]),s[48]||(s[48]=t(`<h3 id="安裝和配置-iscsi" tabindex="-1">安裝和配置 iSCSI <a class="header-anchor" href="#安裝和配置-iscsi" aria-label="Permalink to “安裝和配置 iSCSI”">​</a></h3><p>為了給我們的客户端提供網絡引導鏡像，安裝 <code>scsi-target-utils</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install -y scsi-target-utils</span></span></code></pre></div><p>配置 iSCSI 守護程序去提供 <code>fc28.img</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_REVERSE_HOSTNAME=$(echo $MY_HOSTNAME | tr &#39;.&#39; &quot;\\n&quot; | tac | tr &quot;\\n&quot; &#39;.&#39; | cut -b -\${#MY_HOSTNAME})</span></span>
<span class="line"><span># cat &lt;&lt; END &gt; /etc/tgt/conf.d/fc28.conf</span></span>
<span class="line"><span>&lt;target iqn.$MY_REVERSE_HOSTNAME:fc28&gt;</span></span>
<span class="line"><span>  backing-store /fc28.img</span></span>
<span class="line"><span>  readonly 1</span></span>
<span class="line"><span>&lt;/target&gt;</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>開頭的 <code>iqn.</code> 是 <code>/usr/lib/dracut/modules.d/40network/net-lib.sh</code> 所需要的。</p><p>添加一個防火牆例外，並啓用和啓動這個服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --add-service=iscsi-target</span></span>
<span class="line"><span># firewall-cmd --runtime-to-permanent</span></span>
<span class="line"><span># systemctl enable tgtd.service</span></span>
<span class="line"><span># systemctl start tgtd.service</span></span></code></pre></div><p>你現在應該能夠使用 <code>tatadm</code> 命令看到這個鏡像共享了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tgtadm --mode target --op show</span></span></code></pre></div><p>上述命令的輸出應該類似如下的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Target 1: iqn.edu.example.server-01:fc28</span></span>
<span class="line"><span>    System information:</span></span>
<span class="line"><span>        Driver: iscsi</span></span>
<span class="line"><span>        State: ready</span></span>
<span class="line"><span>    I_T nexus information:</span></span>
<span class="line"><span>    LUN information:</span></span>
<span class="line"><span>        LUN: 0</span></span>
<span class="line"><span>            Type: controller</span></span>
<span class="line"><span>            SCSI ID: IET     00010000</span></span>
<span class="line"><span>            SCSI SN: beaf10</span></span>
<span class="line"><span>            Size: 0 MB, Block size: 1</span></span>
<span class="line"><span>            Online: Yes</span></span>
<span class="line"><span>            Removable media: No</span></span>
<span class="line"><span>            Prevent removal: No</span></span>
<span class="line"><span>            Readonly: No</span></span>
<span class="line"><span>            SWP: No</span></span>
<span class="line"><span>            Thin-provisioning: No</span></span>
<span class="line"><span>            Backing store type: null</span></span>
<span class="line"><span>            Backing store path: None</span></span>
<span class="line"><span>            Backing store flags: </span></span>
<span class="line"><span>        LUN: 1</span></span>
<span class="line"><span>            Type: disk</span></span>
<span class="line"><span>            SCSI ID: IET     00010001</span></span>
<span class="line"><span>            SCSI SN: beaf11</span></span>
<span class="line"><span>            Size: 10488 MB, Block size: 512</span></span>
<span class="line"><span>            Online: Yes</span></span>
<span class="line"><span>            Removable media: No</span></span>
<span class="line"><span>            Prevent removal: No</span></span>
<span class="line"><span>            Readonly: Yes</span></span>
<span class="line"><span>            SWP: No </span></span>
<span class="line"><span>            Thin-provisioning: No</span></span>
<span class="line"><span>            Backing store type: rdwr</span></span>
<span class="line"><span>            Backing store path: /fc28.img</span></span>
<span class="line"><span>            Backing store flags:</span></span>
<span class="line"><span>    Account information:</span></span>
<span class="line"><span>    ACL information:</span></span>
<span class="line"><span>        ALL</span></span></code></pre></div><p>現在，我們可以去刪除本系列文章的第一部分中創建的 NFS 共享了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rm -f /etc/exports.d/fc28.exports</span></span>
<span class="line"><span># exportfs -rv</span></span>
<span class="line"><span># umount /export/fc28</span></span>
<span class="line"><span># rmdir /export/fc28</span></span>
<span class="line"><span># sed -i &#39;/^\\/fc28 /d&#39; /etc/fstab</span></span></code></pre></div><p>你也可以刪除 <code>/fc28</code> 文件系統，但為了以後進一步更新，你可能需要保留它。</p><h3 id="更新-esp-去使用-iscsi-內核" tabindex="-1">更新 ESP 去使用 iSCSI 內核 <a class="header-anchor" href="#更新-esp-去使用-iscsi-內核" aria-label="Permalink to “更新 ESP 去使用 iSCSI 內核”">​</a></h3><p>更新 ESP 去包含啓用了 iSCSI 的 <code>initramfs</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm -vf $HOME/esp/linux/*.fc28.*</span></span>
<span class="line"><span>$ MY_KRNL=$(ls -c /fc28/lib/modules | head -n 1)</span></span>
<span class="line"><span>$ cp $(find /fc28/lib/modules -maxdepth 2 -name &#39;vmlinuz&#39; | grep -m 1 $MY_KRNL) $HOME/esp/linux/vmlinuz-$MY_KRNL</span></span>
<span class="line"><span>$ cp $(find /fc28/boot -name &#39;init*&#39; | grep -m 1 $MY_KRNL) $HOME/esp/linux/initramfs-$MY_KRNL.img</span></span></code></pre></div><p>更新 <code>boot.cfg</code> 文件去傳遞新的 <code>root</code> 和 <code>netroot</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_NAME=server-01.example.edu</span></span>
<span class="line"><span>$ MY_EMAN=$(echo $MY_NAME | tr &#39;.&#39; &quot;\\n&quot; | tac | tr &quot;\\n&quot; &#39;.&#39; | cut -b -\${#MY_NAME})</span></span>
<span class="line"><span>$ MY_ADDR=$(host -t A $MY_NAME | awk &#39;{print $4}&#39;)</span></span>
<span class="line"><span>$ sed -i &quot;s! root=[^ ]*! root=/dev/disk/by-path/ip-$MY_ADDR:3260-iscsi-iqn.$MY_EMAN:fc28-lun-1 netroot=iscsi:$MY_ADDR::::iqn.$MY_EMAN:fc28!&quot; $HOME/esp/linux/boot.cfg</span></span></code></pre></div><p>現在，你只需要從 <code>$HOME/esp/linux</code> 目錄中複製更新後的文件到所有客户端系統的 ESP 中。你應該會看到類似下面屏幕截圖的結果：</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/12/netboot-screenshot-1024x819.png" alt=""></p><h3 id="更新鏡像" tabindex="-1">更新鏡像 <a class="header-anchor" href="#更新鏡像" aria-label="Permalink to “更新鏡像”">​</a></h3><p>首先，複製出一個當前鏡像的副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp -a /fc28 /fc29</span></span></code></pre></div><p><code>chroot</code> 進入到鏡像的新副本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># for i in dev dev/pts dev/shm proc sys run; do mount -o bind /$i /fc29/$i; done</span></span>
<span class="line"><span># chroot /fc29 /usr/bin/bash --login</span></span></code></pre></div><p>允許更新內核：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -i &#39;s/^exclude=kernel-\\*$/#exclude=kernel-*/&#39; /etc/dnf/dnf.conf</span></span></code></pre></div><p>執行升級：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf distro-sync -y --releasever=29</span></span></code></pre></div><p>阻止更新過的內核被再次更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sed -i &#39;s/^#exclude=kernel-\\*$/exclude=kernel-*/&#39; /etc/dnf/dnf.conf</span></span></code></pre></div><p>上述命令是可選的，但是在以後，如果在鏡像中添加和更新了幾個包，在你的客户端之外保存有一個最新內核的副本，會在關鍵時刻對你非常有幫助。</p><p>清理 dnf 的包緩存：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf clean all</span></span></code></pre></div><p>退出 chroot 並清理 root 的命令歷史：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># logout</span></span>
<span class="line"><span># for i in run sys proc dev/shm dev/pts dev; do umount /fc29/$i; done</span></span>
<span class="line"><span># &gt; /fc29/root/.bash_history</span></span></code></pre></div><p>創建 iSCSI 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># FC29_SIZE=$(du -ms /fc29 | cut -f 1)</span></span>
<span class="line"><span># dd if=/dev/zero of=/fc29.img bs=1MiB count=0 seek=$(($FC29_SIZE*2))</span></span>
<span class="line"><span># mkfs -t xfs -L NETROOT /fc29.img</span></span>
<span class="line"><span># TEMP_MNT=$(mktemp -d)</span></span>
<span class="line"><span># mount /fc29.img $TEMP_MNT</span></span>
<span class="line"><span># cp -a /fc29/* $TEMP_MNT</span></span>
<span class="line"><span># umount $TEMP_MNT</span></span></code></pre></div><p>定義一個新的 iSCSI 目標，指向到新的鏡像並導出它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># MY_HOSTNAME=$(&lt;/etc/hostname)</span></span>
<span class="line"><span># MY_REVERSE_HOSTNAME=$(echo $MY_HOSTNAME | tr &#39;.&#39; &quot;\\n&quot; | tac | tr &quot;\\n&quot; &#39;.&#39; | cut -b -\${#MY_HOSTNAME})</span></span>
<span class="line"><span># cat &lt;&lt; END &gt; /etc/tgt/conf.d/fc29.conf</span></span>
<span class="line"><span>&lt;target iqn.$MY_REVERSE_HOSTNAME:fc29&gt;</span></span>
<span class="line"><span> backing-store /fc29.img</span></span>
<span class="line"><span> readonly 1</span></span>
<span class="line"><span>&lt;/target&gt;</span></span>
<span class="line"><span>END</span></span>
<span class="line"><span># tgt-admin --update ALL</span></span></code></pre></div><p>添加新內核和 <code>initramfs</code> 到 ESP：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_KRNL=$(ls -c /fc29/lib/modules | head -n 1)</span></span>
<span class="line"><span>$ cp $(find /fc29/lib/modules -maxdepth 2 -name &#39;vmlinuz&#39; | grep -m 1 $MY_KRNL) $HOME/esp/linux/vmlinuz-$MY_KRNL</span></span>
<span class="line"><span>$ cp $(find /fc29/boot -name &#39;init*&#39; | grep -m 1 $MY_KRNL) $HOME/esp/linux/initramfs-$MY_KRNL.img</span></span></code></pre></div><p>更新 ESP 的 <code>boot.cfg</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ MY_DNS1=192.0.2.91</span></span>
<span class="line"><span>$ MY_DNS2=192.0.2.92</span></span>
<span class="line"><span>$ MY_NAME=server-01.example.edu</span></span>
<span class="line"><span>$ MY_EMAN=$(echo $MY_NAME | tr &#39;.&#39; &quot;\\n&quot; | tac | tr &quot;\\n&quot; &#39;.&#39; | cut -b -\${#MY_NAME})</span></span>
<span class="line"><span>$ MY_ADDR=$(host -t A $MY_NAME | awk &#39;{print $4}&#39;)</span></span>
<span class="line"><span>$ cat &lt;&lt; END &gt; $HOME/esp/linux/boot.cfg</span></span>
<span class="line"><span>#!ipxe</span></span>
<span class="line"><span></span></span>
<span class="line"><span>kernel --name kernel.efi \\\${prefix}/vmlinuz-$MY_KRNL initrd=initrd.img ro ip=dhcp rd.peerdns=0 nameserver=$MY_DNS1 nameserver=$MY_DNS2 root=/dev/disk/by-path/ip-$MY_ADDR:3260-iscsi-iqn.$MY_EMAN:fc29-lun-1 netroot=iscsi:$MY_ADDR::::iqn.$MY_EMAN:fc29 console=tty0 console=ttyS0,115200n8 audit=0 selinux=0 quiet</span></span>
<span class="line"><span>initrd --name initrd.img \\\${prefix}/initramfs-$MY_KRNL.img</span></span>
<span class="line"><span>boot || exit</span></span>
<span class="line"><span>END</span></span></code></pre></div><p>最後，從我的 <code>$HOME/esp/linux</code> 目錄中複製文件到所有客户端系統的 ESP 中去使用它吧！</p><hr>`,48)),a("p",null,[s[28]||(s[28]=n("via: ",-1)),e(i,{href:"https://fedoramagazine.org/how-to-build-a-netboot-server-part-2/"},{default:p(()=>[...s[27]||(s[27]=[n("https://fedoramagazine.org/how-to-build-a-netboot-server-part-2/",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("作者：",-1)),e(i,{href:"https://fedoramagazine.org/author/glb/"},{default:p(()=>[...s[29]||(s[29]=[n("Gregory Bartholomew",-1)])]),_:1}),s[34]||(s[34]=n(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[30]||(s[30]=[n("lujun9972",-1)])]),_:1}),s[35]||(s[35]=n(" 譯者：",-1)),e(i,{href:"https://github.com/qhwdw"},{default:p(()=>[...s[31]||(s[31]=[n("qhwdw",-1)])]),_:1}),s[36]||(s[36]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:p(()=>[...s[32]||(s[32]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[39]||(s[39]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[37]||(s[37]=[n("LCTT",-1)])]),_:1}),s[40]||(s[40]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:p(()=>[...s[38]||(s[38]=[n("Linux中國",-1)])]),_:1}),s[41]||(s[41]=n(" 榮譽推出",-1))])])}const v=l(r,[["render",h]]);export{y as __pageData,v as default};
